mapper.select:
SELECT b.id, b.target_type, b.target_value, b.reason, b.blacklist_time, b.expire_time, b.status, b.operator_id, b.operator_name, b.remark, b.create_time FROM yms_blacklist b WHERE b.deleted = 0
AND b.target_type = #{bo.targetType}
AND b.target_value LIKE CONCAT('%', #{bo.targetValue}, '%')
AND b.status = #{bo.status}
ORDER BY b.blacklist_time DESC
